const listAgentTasks = `-- name: ListAgentTasks :many
SELECT x.id, x.uuid, x.organization_id, x.engagement_id, x.kind, x.run_uuid, x.sequence, x.period, x.kinds, x.status, x.progress, x.server_report, x.error_code, x.error_message, x.resolution, x.requested_by, x.approved_by, x.approved_at, x.resolved_by, x.agent_id, x.claimed_at, x.finished_at, x.created_at, x.updated_at, e.uuid AS engagement_uuid, e.taxpayer_id, e.status AS engagement_status, e.started_at AS engagement_started_at,
       t.uuid AS taxpayer_uuid, t.title AS taxpayer_title, COALESCE(t.tax_id, '')::text AS taxpayer_tax_id,
       a.uuid AS agent_uuid, a.name AS agent_name,
       btrim(COALESCE(ru.name, '') || ' ' || COALESCE(ru.surname, ''))::text AS requested_by_name,
       btrim(COALESCE(au.name, '') || ' ' || COALESCE(au.surname, ''))::text AS approved_by_name,
       count(*) OVER ()::bigint AS total
FROM agent_tasks x
JOIN engagements e ON e.organization_id = x.organization_id AND e.id = x.engagement_id
JOIN taxpayers t ON t.id = e.taxpayer_id
LEFT JOIN desktop_agents a ON a.id = x.agent_id AND a.organization_id = x.organization_id
LEFT JOIN users ru ON ru.id = x.requested_by
LEFT JOIN users au ON au.id = x.approved_by
WHERE x.organization_id = $1
  AND ($2::bool OR x.engagement_id IN (
        SELECT g.engagement_id FROM engagement_assignments g
        WHERE g.organization_id = $1 AND g.user_id = $3))
  AND ($4::text IS NULL OR x.status = $4)
  AND (NOT $5::bool OR x.status IN ('queued', 'claimed', 'waiting_user', 'running'))
  AND ($6::text IS NULL OR x.kind = $6)
  AND ($7::uuid IS NULL OR x.run_uuid = $7)
  AND ($8::uuid IS NULL OR e.uuid = $8)
ORDER BY x.created_at DESC, x.run_uuid, x.sequence, x.id DESC
LIMIT $10 OFFSET $9
`

