const listMissingCounterparties = `-- name: ListMissingCounterparties :many
SELECT DISTINCT ON (x.tax_id, x.main_code) x.tax_id::text AS tax_id, x.main_code::text AS main_code, x.title::text AS title
FROM (
    SELECT COALESCE(NULLIF(i.customer_tax_number, ''), i.customer_identity_number) AS tax_id,
           CASE WHEN i.direction = 'incoming' THEN '320' ELSE '120' END AS main_code,
           COALESCE(i.customer_name, '') AS title, i.id
    FROM invoices i
    WHERE i.taxpayer_id = $1 AND i.period = $2
) x
WHERE x.tax_id ~ '^[0-9]{10,11}$'
  AND NOT EXISTS (
    SELECT 1 FROM counterparty_accounts c
    WHERE c.organization_id = $3 AND c.engagement_id = $4
      AND c.counterparty_tax_id = x.tax_id AND c.main_code = x.main_code)
ORDER BY x.tax_id, x.main_code, x.id
LIMIT 500
`

type ListMissingCounterpartiesParams struct {
	TaxpayerID     int64  `json:"taxpayer_id"`
	Period         string `json:"period"`
	OrganizationID int64  `json:"organization_id"`
	EngagementID   int64  `json:"engagement_id"`
}

type ListMissingCounterpartiesRow struct {
	TaxID    string `json:"tax_id"`
	MainCode string `json:"main_code"`
	Title    string `json:"title"`
}

// Dönemin faturalarında cari hafızasında olmayan karşı taraflar: gelen
// fatura satıcıdır (320), giden fatura alıcıdır (120).
func (q *Queries) ListMissingCounterparties(ctx context.Context, arg ListMissingCounterpartiesParams) ([]ListMissingCounterpartiesRow, error) {
	rows, err := q.db.Query(ctx, listMissingCounterparties,
		arg.TaxpayerID,
		arg.Period,
		arg.OrganizationID,
		arg.EngagementID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListMissingCounterpartiesRow{}
	for rows.Next() {
		var i ListMissingCounterpartiesRow
		if err := rows.Scan(&i.TaxID, &i.MainCode, &i.Title); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

